create table if not exists content_items(id uuid primary key default gen_random_uuid(),type text not null,title text,body text,status text default 'idea',scheduled_at timestamptz,published_at timestamptz,external_id text,metadata jsonb default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists publishing_queue(id uuid primary key default gen_random_uuid(),content_id uuid references content_items(id),target text not null,scheduled_for timestamptz,status text default 'queued',attempts int default 0,idempotency_key text unique,error_message text,published_at timestamptz,created_at timestamptz default now());
create table if not exists voice_profiles(id uuid primary key default gen_random_uuid(),name text not null,description text,preferred_words jsonb default '[]',forbidden_words jsonb default '[]',tone text,structure_rules text,examples jsonb default '[]',created_at timestamptz default now());
create table if not exists metrics(id uuid primary key default gen_random_uuid(),content_id uuid references content_items(id),metric_type text not null,metric_value numeric,captured_at timestamptz default now(),metadata jsonb default '{}');
create table if not exists audit_events(id uuid primary key default gen_random_uuid(),actor_type text,actor_id text,action text,target_type text,target_id text,request jsonb,response jsonb,success boolean,created_at timestamptz default now());